-- ── artist_delegates ──────────────────────────────────────────

CREATE POLICY "artist_delegates_delete" ON artist_delegates
  FOR DELETE
  USING (auth.uid() = artist_id);

CREATE POLICY "artist_delegates_insert" ON artist_delegates
  FOR INSERT
  WITH CHECK (auth.uid() = artist_id);

CREATE POLICY "artist_delegates_select" ON artist_delegates
  FOR SELECT
  USING ((auth.uid() = artist_id) OR (auth.uid() = delegate_id));

CREATE POLICY "artist_delegates_update" ON artist_delegates
  FOR UPDATE
  USING (auth.uid() = delegate_id);

-- ── attachments ────────────────────────────────────────────────

CREATE POLICY "attachments_own" ON attachments
  FOR ALL
  USING (EXISTS ( SELECT 1
   FROM performances
  WHERE ((performances.id = attachments.performance_id) AND (performances.user_id = auth.uid()))));

-- ── beta_invites ───────────────────────────────────────────────

CREATE POLICY "service_role_all" ON beta_invites
  FOR ALL
  TO service_role
  USING (true)
  WITH CHECK (true);

CREATE POLICY "users_accept_own_invite" ON beta_invites
  FOR UPDATE
  TO authenticated
  USING (email = (auth.jwt() ->> 'email'::text))
  WITH CHECK (email = (auth.jwt() ->> 'email'::text));

CREATE POLICY "users_read_own_invite" ON beta_invites
  FOR SELECT
  USING (email = (auth.jwt() ->> 'email'::text));

