CREATE POLICY "capture_sessions_own" ON capture_sessions
  FOR ALL
  USING (EXISTS ( SELECT 1
   FROM performances
  WHERE ((performances.id = capture_sessions.performance_id) AND (performances.user_id = auth.uid()))));

