CREATE POLICY "rd_log_superadmin_all" ON rd_log
  FOR ALL
  USING ((auth.jwt() ->> 'email'::text) = ANY (ARRAY['jesse.slack.music@gmail.com'::text, 'darylscottsongs@gmail.com'::text]))
  WITH CHECK ((auth.jwt() ->> 'email'::text) = ANY (ARRAY['jesse.slack.music@gmail.com'::text, 'darylscottsongs@gmail.com'::text]));

